package local.bo2beta;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.client.CameraType;
import net.minecraft.client.Screenshot;
import net.minecraft.world.level.GameType;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.core.BlockPos;
import net.minecraft.world.phys.Vec3;
/** Lifecycle assertions run exclusively in the disposable packaged smoke world. */
public final class MatchSmoke {
    private static int stage,ticks,wait,skinIndex;
    private static volatile Throwable failure;
    private static final AtomicBoolean ready=new AtomicBoolean();
    private static int handStart,fireStart,reloadStart,pinStart;
    private static UUID originalBot;
    private static Vec3 originalSpawn;
    private static String originalKit;
    private static final List<String> skins=new ArrayList<>(BotCharacters.NAMES.keySet());
    private static void check(boolean result,String message){if(!result)throw new AssertionError(message);}
    private static void task(Minecraft c,Runnable action){ready.set(false);c.getSingleplayerServer().execute(()->{try{action.run();}catch(Throwable ex){failure=ex;}finally{ready.set(true);}});}
    private static net.minecraft.server.level.ServerPlayer player(Minecraft c){return c.getSingleplayerServer().getPlayerList().getPlayers().get(0);}
    private static MatchDirector.Entry enemy(){return MatchDirector.session.roster.stream().filter(e->!e.human && (MatchDirector.session.mode!=MatchDirector.Mode.TDM || e.team!=0) && e.entity.isAlive()).findFirst().orElseThrow();}
    private static void kill(Minecraft c,MatchDirector.Entry victim){var p=player(c);victim.entity.invulnerableTime=0;check(victim.entity.hurt(p.damageSources().playerAttack(p),1000),"Match damage rejected");check(!victim.entity.isAlive(),"Victim did not die");}
    private static void playing(){MatchDirector.session.countdownEnd=MatchDirector.session.level.getGameTime();MatchDirector.tick(MatchDirector.session.level.getServer());for(var e:MatchDirector.session.roster)if(e.entity instanceof Bo2Bot bot)bot.setNoAi(true);}
    private static void respawnNow(Minecraft c){for(var e:MatchDirector.session.roster)if(e.respawnAt>=0)e.respawnAt=0;MatchDirector.tick(c.getSingleplayerServer());for(var e:MatchDirector.session.roster)if(e.entity instanceof Bo2Bot b)b.setNoAi(true);}
    public static void tick(Minecraft c){
        c.options.pauseOnLostFocus=false;if(failure!=null)throw new AssertionError("Match smoke server assertion",failure);
        if(++ticks>6000)throw new AssertionError("Match smoke timeout stage "+stage);
        if(stage==0 && c.screen instanceof TitleScreen){c.createWorldOpenFlows().loadLevel(c.screen,"BetaSmoke");stage=1;return;}
        if(c.getSingleplayerServer()==null || c.player==null || c.level==null)return;
        if(stage==1 && ++wait>85){c.setScreen(null);task(c,()->{var p=player(c);if(!p.isAlive() || p.isRemoved()){p=c.getSingleplayerServer().getPlayerList().respawn(p,false);p.connection.player=p;}p.setGameMode(GameType.CREATIVE);p.setHealth(20);p.setNoGravity(false);p.serverLevel().setDefaultSpawnPos(new BlockPos(1633,20,-784),0);p.connection.teleport(1633.5,20,-784.5,0,0);p.getInventory().clearContent();p.getInventory().setItem(8,new ItemStack(Items.DIAMOND,7));BoundarySmoke.verify(p);check(MatchDirector.start(p,MatchDirector.Mode.TDM,4,2,5),"TDM start");check(MatchDirector.session.roster.size()==5,"Exact requested bot count");check(MatchDirector.session.roster.stream().filter(e->e.team==0).count()==3,"Balanced teams");check(!MatchDirector.start(p,MatchDirector.Mode.FFA,2,2,5),"Duplicate match accepted");check(!enemy().entity.hurt(p.damageSources().playerAttack(p),1),"Countdown allowed damage");for(var e:MatchDirector.session.roster){check(MatchDirector.safe(p.serverLevel(),e.entity,e.lastSpawn) && MatchDirector.insideArena(e.lastSpawn),"Unsafe or out-of-arena spawn");check(e.secondary!=null && Beta.GUNS.containsKey(e.primary) && Beta.GUNS.containsKey(e.secondary),"Random complete loadout");if(!e.human)check(BotCharacters.valid(e.skin) && !e.skin.equals("cdc"),"Bot custom random skin");}p.connection.teleport(1500,20,-700,0,0);for(int boundaryTick=0;boundaryTick<20;boundaryTick++)MatchDirector.tick(p.server);check(MatchDirector.insideArena(p.position()),"Arena boundary correction: p="+p.position()+" alive="+p.isAlive()+" map="+MatchDirector.session.roster.get(0).entity.position()+" connection="+(p.connection.player==p)+" last="+MatchDirector.session.roster.get(0).lastSpawn+" phase="+MatchDirector.session.phase+" same="+(p==MatchDirector.session.roster.get(0).entity)+" current="+player(c).position());playing();BoundarySmoke.verify(p);var friend=MatchDirector.session.roster.stream().filter(e->!e.human && e.team==0).findFirst().orElseThrow();check(!friend.entity.hurt(p.damageSources().playerAttack(p),1),"Friendly fire");check(!((Bo2Bot)friend.entity).validTarget(p),"Friendly targeting");var e=enemy();originalBot=e.entity.getUUID();originalSpawn=e.lastSpawn;originalKit=e.primary;kill(c,e);check(MatchDirector.session.teamScores[0]==1 && e.deaths==1,"TDM kill/death scoring");});stage=2;wait=0;return;}
        if(stage==2 && ready.get() && ++wait>5){task(c,()->{respawnNow(c);var e=MatchDirector.session.roster.stream().filter(r->!r.human && r.deaths==1).findFirst().orElseThrow();check(!e.entity.getUUID().equals(originalBot),"Bot did not respawn");check(e.lastSpawn.distanceToSqr(originalSpawn)>=9 && MatchDirector.safe(MatchDirector.session.level,e.entity,e.lastSpawn),"Random safe bot respawn");check(e.deaths==1,"Respawn lost score");kill(c,enemy());check(MatchDirector.session.phase==MatchDirector.Phase.FINISHED,"TDM score-limit win");check(MatchDirector.stop(player(c)),"Host end");check(player(c).isCreative() && player(c).getInventory().getItem(8).getCount()==7,"Lobby inventory/gamemode restore");check(MatchDirector.entities.isEmpty(),"Match cleanup");check(MatchDirector.start(player(c),MatchDirector.Mode.FFA,3,3,5),"FFA start");playing();for(var a:MatchDirector.session.roster)for(var b:MatchDirector.session.roster)if(a!=b)check(MatchDirector.target(a.entity,b.entity),"FFA opponent rules");kill(c,enemy());check(MatchDirector.session.roster.get(0).score==1,"FFA individual score");var p=player(c);PlayerCharacters.select(p,"chun-li-fortnite-skin");originalSpawn=p.position();p.invulnerableTime=0;p.hurt(Beta.bulletDamage(enemy().entity),1000);check(!p.isAlive(),"Human death: health="+p.getHealth()+" invulnerable="+p.getAbilities().invulnerable+" tick="+p.tickCount+" phase="+MatchDirector.session.phase);});stage=3;wait=0;return;}
        if(stage==3 && ready.get() && ++wait>5){task(c,()->{respawnNow(c);var p=player(c);check(p.isAlive() && p.gameMode.getGameModeForPlayer()==GameType.ADVENTURE,"Automatic player respawn");check(p.position().distanceToSqr(originalSpawn)>=9,"Random player spawn");check(PlayerCharacters.character(p).equals("chun-li-fortnite-skin"),"Character persists through death");check(p.getInventory().getItem(1).getItem() instanceof Beta.Gun && p.getInventory().getItem(2).getCount()==2,"Player random respawn kit");check(MatchDirector.session.roster.get(0).deaths==1,"Player death score");MatchDirector.stop(p);check(MatchDirector.start(p,MatchDirector.Mode.GUN_GAME,2,20,0),"Gun Game start");playing();var gg=MatchDirector.session.roster.get(0);var tierGun=p.getInventory().getItem(0).getItem();p.getInventory().setItem(2,new ItemStack(Beta.GRENADE,2));p.getInventory().selected=2;var grenades=p.getMainHandItem().getCount();for(int i=0;i<10;i++)MatchDirector.tick(p.server);check(p.getInventory().selected==2 && p.getMainHandItem().getItem()==Beta.GRENADE && p.getMainHandItem().getCount()==grenades && p.getInventory().getItem(0).getItem()==tierGun,"Gun Game replaced grenade selection");p.getInventory().selected=0;for(int tier=0;tier<20;tier++){check(MatchDirector.session.roster.get(0).tier==tier,"Gun progression "+tier);check(p.getMainHandItem().getItem()==Beta.GUNS.get(MatchDirector.GUN_LADDER.get(tier)),"Immediate tier weapon "+tier);kill(c,enemy());if(tier<19){check(MatchDirector.session.phase==MatchDirector.Phase.PLAYING,"Gun Game early win");respawnNow(c);}}check(MatchDirector.session.phase==MatchDirector.Phase.FINISHED,"Final-stage win");MatchDirector.stop(p);check(MatchDirector.start(p,MatchDirector.Mode.GUN_GAME,1,20,0),"Gun Game restart");playing();kill(c,enemy());respawnNow(c);p.invulnerableTime=0;p.hurt(p.damageSources().generic(),1000);check(MatchDirector.session.roster.get(0).tier==0,"Gun Game suicide demotion");respawnNow(c);p=player(c);var v=enemy();v.tier=2;v.score=2;v.entity.moveTo(p.getX(),p.getY(),p.getZ()+1.4,0,0);p.setYRot(0);p.setXRot(0);MatchDirector.melee(p);check(!v.entity.isAlive() && v.tier==1 && MatchDirector.session.roster.get(0).tier==0,"Knife humiliation without promotion");
            MatchDirector.stop(player(c));check(MatchDirector.start(player(c),MatchDirector.Mode.FFA,1,100,1),"Timed restart");playing();MatchDirector.session.endTick=0;MatchDirector.tick(c.getSingleplayerServer());check(MatchDirector.session.phase==MatchDirector.Phase.FINISHED && MatchDirector.session.result.equals("Draw"),"Timed draw");MatchDirector.stop(player(c));PlayerCharacters.select(player(c),"default");System.out.println("MATCH SMOKE PASS: Nuketown; bot count; countdown; teams; friendly fire; FFA; random player/bot kits and safe respawns; inventory restore; 20-stage Gun Game; suicide demotion; cleanup");});stage=4;wait=0;return;}
        if(stage==4 && ready.get()){c.setScreen(new LobbyScreen());Screenshot.grab(c.gameDirectory,"nuketown-lobby.png",c.getMainRenderTarget(),m->{});stage=5;wait=0;return;}
        if(stage==5 && ++wait>20){Screenshot.grab(c.gameDirectory,"nuketown-lobby.png",c.getMainRenderTarget(),m->{});c.setScreen(null);c.options.setCameraType(CameraType.THIRD_PERSON_FRONT);stage=6;wait=0;return;}
        if(stage==6){if(skinIndex>=skins.size()){task(c,()->PlayerCharacters.select(player(c),"default"));stage=8;return;}String skin=skins.get(skinIndex);task(c,()->{PlayerCharacters.select(player(c),skin);});stage=7;wait=0;return;}
        if(stage==7 && ready.get() && ++wait>30){check(PlayerCharacterClient.skin(c.player.getUUID()).equals(skins.get(skinIndex)),"Character synchronization");check(PlayerCharacterRenderer.frames>0,"Player character renderer");Screenshot.grab(c.gameDirectory,"player-"+skins.get(skinIndex)+".png",c.getMainRenderTarget(),m->{});skinIndex++;stage=6;return;}
        if(stage==8 && ready.get()){if(!PlayerCharacterClient.skin(c.player.getUUID()).equals("default"))return;System.out.println("MATCH CHARACTER PASS: all "+skins.size()+" playable characters and default reset; custom render frames="+PlayerCharacterRenderer.frames);c.options.setCameraType(CameraType.FIRST_PERSON);skinIndex=0;stage=9;}
        if(stage==9){c.options.keyUse.setDown(false);if(skinIndex>=skins.size()){task(c,()->{PlayerCharacters.select(player(c),"default");player(c).getInventory().clearContent();player(c).getInventory().setItem(8,new ItemStack(Items.DIAMOND,7));});stage=11;return;}String skin=skins.get(skinIndex);handStart=PlayerCharacterClient.handFrames;fireStart=OriginalView.renderedFireFrames;reloadStart=OriginalView.renderedReloadFrames;pinStart=OriginalGrenadeView.pinFrames;task(c,()->{var p=player(c);p.setGameMode(GameType.ADVENTURE);p.getInventory().setItem(0,new ItemStack(Beta.GUNS.get("ar_ak47")));p.getInventory().selected=0;PlayerCharacters.select(p,skin);Beta.resetWeapon(p);});stage=10;wait=0;return;}
        if(stage==10 && ready.get()){
            ++wait;String name=skins.get(skinIndex);
            if(wait>=12 && wait<20)c.options.keyAttack.setDown(true);
            if(wait==12){Screenshot.grab(c.gameDirectory,"first-person-"+name+".png",c.getMainRenderTarget(),m->{});c.options.keyAttack.setDown(true);}
            if(wait==16)Screenshot.grab(c.gameDirectory,"first-person-fire-"+name+".png",c.getMainRenderTarget(),m->{});
            if(wait==20){System.out.println("WEAPON INPUT TRACE: "+name+" clientHand="+c.player.getMainHandItem()+" screen="+c.screen+" state="+BetaClient.state);task(c,()->System.out.println("WEAPON SERVER TRACE: "+name+" "+Beta.weaponDebug(player(c))));c.options.keyAttack.setDown(false);BetaClient.send("reload","",false,false);}
            if(wait==36)Screenshot.grab(c.gameDirectory,"first-person-reload-"+name+".png",c.getMainRenderTarget(),m->{});
            if(wait==65)task(c,()->{var p=player(c);p.getInventory().setItem(0,new ItemStack(Beta.GRENADE,2));});
            if(wait==70){c.options.keyUse.setDown(true);task(c,()->{var p=player(c);check(GrenadeController.begin(p,p.getMainHandItem()),"Grenade begin rejected "+name+" item="+p.getMainHandItem());});}
            if(wait==85){task(c,()->GrenadeController.cancel(player(c)));check(OriginalView.renderedFireFrames>fireStart,"Fire animation missing "+name+" state="+BetaClient.state);check(OriginalView.renderedReloadFrames>reloadStart,"Reload animation missing "+name);check(OriginalGrenadeView.pinFrames>pinStart,"Grenade pin animation missing "+name);if(!name.equals("cdc"))check(PlayerCharacterClient.handFrames>handStart,"Custom first-person arms did not render "+name);Screenshot.grab(c.gameDirectory,"first-person-grenade-"+name+".png",c.getMainRenderTarget(),m->{});skinIndex++;stage=9;return;}
        }
        if(stage==11 && ready.get()){System.out.println("MATCH FIRST PERSON PASS: all 8 custom arm skins plus original CDC; frames="+PlayerCharacterClient.handFrames);task(c,()->{check(MatchDirector.start(player(c),MatchDirector.Mode.FFA,6,100,0),"Live FFA start");MatchDirector.session.countdownEnd=0;MatchDirector.tick(c.getSingleplayerServer());});stage=12;wait=0;return;}
        if(stage==12 && ready.get()){if(c.player.isAlive() && c.screen instanceof net.minecraft.client.gui.screens.DeathScreen)c.setScreen(null);if(++wait<500)return;Screenshot.grab(c.gameDirectory,"nuketown-live-match.png",c.getMainRenderTarget(),m->{});task(c,()->{MatchDirector.tick(c.getSingleplayerServer());int kills=MatchDirector.session.roster.stream().mapToInt(e->e.kills).sum();check(kills>0,"Live bots did not make a kill in Nuketown");for(var e:MatchDirector.session.roster)if(e.entity!=null && e.entity.isAlive())check(MatchDirector.withinMovementBounds(e.entity.position()),"Live actor left arena: "+e.name+" at "+e.entity.position());System.out.println("MATCH LIVE COMBAT PASS: 6 bots, autonomous gunfire, kills="+kills+", automatic respawns, arena confinement");MatchDirector.stop(player(c));});stage=13;return;}
        if(stage==13 && ready.get()){if(AimSmoke.tick(c))stage=14;}
        if(stage==14 && ready.get()){if(CombatSmoke.tick(c))c.stop();}
    }
}
